mapper.sql:

WHERE 1=1 
	AND EDR.업체코드 = #{bcncCode}
	AND EDR.착지업체 = #{alocEntrps}
	AND EDR.출고사업장 = #{registBplc}

WHERE 1=1 AND WB.거래처코드 = #{bcncCode} AND WB.착지업체 = #{alocEntrps} AND (UPC.거래정지일자 = '00000000' OR UPC.거래정지일자 >=CONVERT(VARCHAR,GETDATE(),112) ) AND IC.폐기일자 <= CONVERT(VARCHAR,GETDATE(),112) AND 0 = ( SELECT COUNT(*) FROM 웹주문접수 WO2 WHERE WB.거래처코드 = WO2.거래처코드 AND WB.일자 = WO2.장바구니일자 AND WB.일련번호 = WO2.장바구니번호 AND WO2.접수삭제 = 'N' )
AND WB.납기일자 > #{searchDtFrom} AND WB.납기일자 <= #{searchDtTo}
AND IC.품목명 LIKE UPPER('%'+ #{searchItemNm} +'%')

update.foreach:
UPDATE 웹장바구니 SET
		수량 = #{item.oQuantity}
		, 그룹수량 = #{item.oGrpQy}
		, 낱개수량 = #{item.oPieceQy}
		, 중량= #{item.oWt}
		, 단가 = #{item.oNewUnitpc}
		, 공급가액 = #{item.oSplpcAm}
		, 부가세 = #{item.oVat}
		, 합계금액 = #{item.oSumAm}
		, 납기일자 = #{item.itemDedt}
		, 주문비고 = #{item.oNote}
		, 선택여부 = #{item.oChgAt}
		, 수정자 = #{bcncCode}
		, 수정일자 = CONVERT(VARCHAR,GETDATE(),112)
		, 수정시간 = REPLACE(CONVERT(VARCHAR,GETDATE(),108),':','')
	WHERE 거래처코드 = #{bcncCode} 
	AND 일자 = #{item.oDe}
	AND 일련번호 = #{item.oSn}

delete.foreach:
DELETE FROM 웹장바구니
WHERE 거래처코드 = #{bcncCode} 
AND 일자 = #{item.oDe}
AND 일련번호 = #{item.oSn}

insert.foreach:
INSERT INTO 
	웹주문접수
		(
			접수일자
			, 일련번호
			, 장바구니일자
			, 장바구니번호
			, 단가사업장
			, 거래처코드
			, 품목코드
			, 단가단위
			, 단가단위문자
			, 수량
			, 그룹수량
			, 낱개수량
			, 중량
			, 단가
			, 기준단가
			, 공급가액
			, 부가세
			, 합계금액
			, 납기일자
			, 주문비고
			, 착지업체
			, 출고사업장

			, 거래처재고중량
			, 등록자
			, 등록일자
			, 등록시간
			, 수정자
			, 수정일자
			, 수정시간
	)
	VALUES(
			CONVERT(VARCHAR,GETDATE(),112) 
			, (SELECT ISNULL(MAX(일련번호+1),1) FROM 웹주문접수 WHERE 1=1 AND 접수일자 = #{oDate}) 
			, #{item.oDate} 
			, #{item.oSn} 
			, #{item.oUnitBplc} 
			, #{bcncCode} 
			, #{item.oItemCode} 
			, #{item.oUntpcUnit} 
			, #{item.oUnitChrctr} 
			, #{item.oQuantity} 
			, #{item.oGrpQy} 
			, #{item.oPieceQy} 
			, #{item.oWt} 
			, #{item.oNewUnitpc} 
			, #{item.oNewUnitpc} 
			, #{item.oSplpcAm} 
			, #{item.oVat} 
			, #{item.oSumAmount} 
			, #{item.oItemDedt} 
			, #{item.oItemNote} 
			, #{item.dlvyEntrps} 
			, #{item.oDlivyBplc} 

			, DBO.웹_재고중량_함수(#{item.oItemDedt}, #{item.oItemCode}, 'B', #{item.oDate}, 0) 
			, #{bcncCode} 
			, CONVERT(VARCHAR,GETDATE(),112) 
			, REPLACE(CONVERT(VARCHAR,GETDATE(),108),':','') 
			, #{bcncCode} 
			, CONVERT(VARCHAR,GETDATE(),112) 
			, REPLACE(CONVERT(VARCHAR,GETDATE(),108),':','') 
	)
